#include "../../models/film_three_finger/SharedFilmSystem.h"
#include "../../models/film_three_finger_resume/ContactRows.h"
#include "../../models/film_rail_tendon/ControlProfile.h"
#include <fstream>
#include <iomanip>
#include <iostream>
using namespace regrip_three_finger;
int main(int argc,char**argv){try{
 if(argc!=3&&argc!=4)throw std::runtime_error("checkpoint,output required");std::ifstream in(argv[1]);std::string magic,token;double time,h;unsigned step;in>>magic>>time>>h>>step>>token;SharedFilmSystem s(Layout(),{0,0,-.001},true,true);s.exactUnresolved=true;const unsigned n=s.initial.size(),nf=s.shared.nf;Eigen::VectorXd q(n),v(n);for(double&x:q)in>>x;for(double&x:v)in>>x;double unused;for(unsigned i=0;i<4;++i)in>>unused;s.shared.M.setZero();for(unsigned f=0;f<3;++f){auto&m=s.shared.films[f].film;for(unsigned i=0;i<m.mass.size();++i){double mass;in>>mass;m.mass[i]=mass;for(unsigned d=0;d<3;++d){unsigned a=3*i+d;if(m.index[a]>=0)s.shared.M(f*nf+m.index[a],f*nf+m.index[a])+=mass*m.weight[a]*m.weight[a];}}}for(unsigned i=0;i<6;++i)for(unsigned j=0;j<6;++j)in>>s.shared.M(3*nf+i,3*nf+j);if(!in)throw std::runtime_error("checkpoint mass/state incomplete");if(argc==4){for(unsigned f=0;f<3;++f){auto row=s.selected(q,f);s.owned[f]=row.triangle;s.features[f]=row.feature;}s.rescanClosest=false;}bool semismooth=argc==4&&std::string(argv[3])=="semismooth";std::vector<regrip_three_resume::ContactOwner>owners;for(unsigned f=0;f<3;++f)owners.push_back({f,s.owned[f],s.features[f]});auto geometry=[&](const auto&x){return semismooth?regrip_three_resume::ownedGeometry(s,x,owners,regrip_three_resume::OwnedFeaturePolicy::ClosestPrimitive):s.geometry(x);};std::ofstream out(argv[2]);out<<std::setprecision(17)<<"stage,time,finger,triangle,feature,gap_mm,normal_velocity_mm_s,force_N,q,v\n";
 auto write=[&](const char*stage,double t,const Eigen::VectorXd&x,const Eigen::VectorXd&vel,const Eigen::VectorXd&lambda){for(unsigned f=0;f<3;++f){auto row=semismooth?s.shared.films[f].geometry(s.local(x,f),s.owned[f]):s.selected(x,f);auto geo=geometry(x);out<<stage<<','<<t<<','<<f<<','<<row.triangle<<','<<row.feature<<','<<row.gap<<','<<geo.J.row(f).dot(vel)<<',';if(lambda.size())out<<lambda(f);else out<<"null";for(const auto*z:{&x,&vel})out<<",\""<<z->transpose()<<'"';out<<'\n';}out.flush();};write("accepted_initial",time,q,v,Eigen::VectorXd());bool rejected=false;
try{auto result=regrip_collocation::persistentRows(s.shared.M,2,q,v,time,h,[&](const auto&x,double t){return s.force(x,regrip_film_rail::ControlProfile::evaluate(t,.0001,.01,.02,.03,true).tension);},geometry,false,[&](const auto&r){rejected=true;write("rejected_initial",time,q,v,r.initialForce);for(const auto&stage:r.stages)write("REJECTED_NOT_COMMITTED",stage.time,stage.q,stage.v,stage.force);});for(const auto&stage:result.stages)write("FROZEN_TRIAL_NOT_SOFA",stage.time,stage.q,stage.v,stage.force);double gap=s.clearance(result.q);for(const auto&stage:result.stages)gap=std::min(gap,s.clearance(stage.q));std::cout<<std::setprecision(17)<<"complete independent fixed-branch step;whole_gap="<<gap<<"\\n";return argc==4&&gap>=-1e-10?0:2;}
 catch(const std::exception&e){std::cout<<"REJECTED diagnostic: "<<e.what()<<" captured="<<rejected<<'\n';return rejected?0:3;}
 }catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
